// Sentences with a number in them: [pattern, (match) => Bangla]
const n = (x) => x;
export const BN_PATTERNS = [
  [/^(\d[\d,]*) orders? to confirm$/, (m) => `${n(m[1])}টি Order confirm করতে হবে`],
  [/^(\d[\d,]*) payouts? overdue · (.+)$/, (m) => `${n(m[1])}টি Payout Overdue · ${m[2]}`],
  [/^(\d[\d,]*) supplier bills? overdue$/, (m) => `${n(m[1])}টি Supplier bill Overdue`],
  [/^(\d[\d,]*) bills? to pay overdue$/, (m) => `${n(m[1])}টি দেওয়ার Bill Overdue`],
  [/^(\d[\d,]*) products? low on stock$/, (m) => `${n(m[1])}টি Product-এর Stock কম`],
  [/^(\d[\d,]*) stock adjustments? to approve$/, (m) => `${n(m[1])}টি Stock ঠিক করা Approve করতে হবে`],
  [/^(\d[\d,]*) purchase orders? to approve$/, (m) => `${n(m[1])}টি Purchase order Approve করতে হবে`],
  [/^(\d[\d,]*) courier returns? to receive$/, (m) => `${n(m[1])}টি Courier ফেরত গ্রহণ করতে হবে`],
  [/^(\d[\d,]*) transfers? on the way$/, (m) => `${n(m[1])}টি Transfer পথে আছে`],
  [/^(\d[\d,]*) invoices? not fully paid$/, (m) => `${n(m[1])}টি Invoice পুরো Paid হয়নি`],
  [/^(\d[\d,]*) (?:orders?)$/, (m) => `${n(m[1])}টি Order`],
  [/^(\d[\d,]*) (?:products?)$/, (m) => `${n(m[1])}টি Product`],
  [/^(\d[\d,]*) (?:items?)$/, (m) => `${n(m[1])}টি আইটেম`],
  [/^(\d[\d,]*) (?:pcs|pieces?)$/, (m) => `${n(m[1])} পিস`],
  [/^(\d[\d,]*) (?:invoices?)$/, (m) => `${n(m[1])}টি Invoice`],
  [/^(\d[\d,]*) (?:days?)$/, (m) => `${n(m[1])} দিন`],
  [/^(\d[\d,]*) selected$/, (m) => `${n(m[1])}টি বাছাই করা`],
  [/^(\d[\d,]*) overdue$/, (m) => `${n(m[1])}টি Overdue`],
  [/^(\d[\d,]*) (?:payouts?) to come$/, (m) => `আরও ${n(m[1])}টি Payout আসবে`],
  [/^(\d[\d,]*) due today$/, (m) => `আজ ${n(m[1])}টি আসার কথা`],
  [/^(\d[\d,]*) left$/, (m) => `${n(m[1])}টি বাকি`],
  [/^(\d[\d,]*) sold$/, (m) => `${n(m[1])}টি বিক্রি`],
  [/^(\d[\d,]*) bills?$/, (m) => `${n(m[1])}টি Bill`],
  [/^Day before (.+)$/, (m) => `আগের দিন ${m[1]}`],
  [/^(\d[\d,]*) delivered · (\d[\d,]*) returned$/, (m) => `${m[1]}টি Delivered · ${m[2]}টি ফেরত`],
  [/^(.+) past the due date$/, (m) => `${m[1]} Due তারিখ পেরিয়ে গেছে`],
  [/^(.+) due from customers$/, (m) => `Customer-দের কাছে ${m[1]} Due`],
  [/^Week (.+)$/, (m) => `সপ্তাহে ${m[1]}`],
  [/^of (.+) · (\d+)%$/, (m) => `${m[1]}-এর ${m[2]}%`],
  [/^(.+) to go · about (.+) a day for (\d+) more days?\.$/, (m) => `আরও ${m[1]} বাকি · বাকি ${m[3]} দিনে দিনে প্রায় ${m[2]}।`],
  [/^(.+) to go\.$/, (m) => `আরও ${m[1]} বাকি।`],
  [/^(.+) · All places · updated (.+)$/, (m) => `${m[1]} · সব জায়গা · ${m[2]}-এ হালনাগাদ`],
  [/^Most: (.+)$/, (m) => `সবচেয়ে বেশি: ${m[1]}`],
  [/^(\d[\d,]*) purchase orders?$/, (m) => `${m[1]}টি Purchase order`],
  [/^(\d[\d,]*) transfers?$/, (m) => `${m[1]}টি Transfer`],
  [/^(৳.+) total$/, (m) => `মোট ${m[1]}`],
  [/^(৳.+) left$/, (m) => `${m[1]} বাকি`],
  [/^(৳.+) due$/, (m) => `${m[1]} Due`],
  [/^(\d[\d,]*) pcs to send$/, (m) => `${m[1]} পিস পাঠাতে বাকি`],
  [/^(net )?([+−]?\d[\d,]*) pcs$/, (m) => `${m[1] ? 'নিট ' : ''}${m[2]} পিস`],
  [/^Not in (.+)$/, (m) => `${m[1]}-এ নেই`],
  [/^Your edition: (.+)$/, (m) => `আপনার সংস্করণ: ${m[1]}`],
  [/^Low stock · (\d[\d,]*)$/, (m) => `Stock কম · ${m[1]}`],
  [/^Showing (\d[\d,]*)[–-](\d[\d,]*) of (\d[\d,]*)(.*)$/, (m) => `${m[3]}টির মধ্যে ${m[1]}–${m[2]}${m[4]}`],
];
